(()=>{'use strict';if(!document.querySelector('#stage'))return;

const stage=document.querySelector('#stage'),photo=document.querySelector('#photo'),intro=document.querySelector('#intro'),story=document.querySelector('#story'),spots=document.querySelector('#spots');
const closedPhoto=document.querySelector('#closed-photo'),doorButton=document.querySelector('.spot.one');
const scenes=[{title:'E quando qualcuno deve passare?',text:'L’anta entra nello spazio che usi. Prima dell’ordine, vale la pena capire cosa resta libero e come ci si muove. La fotografia è illustrativa: sul tuo progetto servono misure e indicazioni del modello.',origin:'52% 67%',scale:1.18},{title:'La cucina si attraversa.',text:'Una persona prepara, l’altra passa. I percorsi fanno parte del progetto quanto i mobili: osserva come si incrociano nelle abitudini di ogni giorno.',origin:'62% 74%',scale:1.65},{title:'Ogni scelta ha un seguito.',text:'Materiali, modelli e lavorazioni cambiano l’uso e il preventivo. Per confrontare due proposte, bisogna capire che cosa comprendono davvero.',origin:'84% 48%',scale:1.6}];let current=0,lastSpot=null,opener=null;
function show(i){if(typeof window.gtag==='function')window.gtag('event','vista90g_hotspot',{source_page:'home',hotspot_id:['lavastoviglie','passaggio','scelte'][i]});current=i;const s=scenes[i];stage.classList.toggle('door-open',i===0||i===1);doorButton.setAttribute('aria-expanded',String(i===0));document.querySelector('#back').textContent=i===0?'← Richiudi la lavastoviglie':'← Scena completa';intro.hidden=true;spots.inert=true;stage.classList.add('active');photo.style.transformOrigin=s.origin;photo.style.transform='scale('+s.scale+')';closedPhoto.style.transformOrigin=s.origin;closedPhoto.style.transform=photo.style.transform;document.querySelector('#step').textContent='0'+(i+1)+' / CAMBIA PROSPETTIVA';document.querySelector('#story-title').textContent=s.title;document.querySelector('#story-text').textContent=s.text;story.hidden=false;story.focus({preventScroll:true})}
function reset(){stage.classList.remove('active','door-open');doorButton.setAttribute('aria-expanded','false');closedPhoto.style.transform='scale(1)';photo.style.transform='scale(1)';story.hidden=true;intro.hidden=false;spots.inert=false;if(lastSpot)lastSpot.focus({preventScroll:true})}
document.querySelectorAll('.spot').forEach(b=>b.addEventListener('click',()=>{lastSpot=b;show(Number(b.dataset.index))}));document.querySelector('#back').addEventListener('click',reset);document.querySelector('#next').addEventListener('click',()=>show((current+1)%scenes.length));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&stage.classList.contains('active'))reset()});
})();
